import { useState } from 'react';
import {
  JxPage,
  JxPageHeader,
  JxBadge,
  JxCard,
  JxSegmentedControl,
  JxSegmentedItem,
  JxSlider,
  JxSwitch,
  JxDivider,
  JxSelect,
  JxSelectItem,
  JxStack,
  JxRow,
  JxText,
} from '@jinx-ui/react';

type Theme = 'light' | 'dark' | 'system';
type Font = 'system' | 'inter' | 'mono';

interface AppearanceSettings {
  theme: Theme;
  scale: number;
  dense: boolean;
  font: Font;
}

interface AppearanceScreenProps {
  onChange?: (settings: AppearanceSettings) => void;
}

const themeLabels: Record<Theme, string> = {
  light: 'Светлая',
  dark: 'Тёмная',
  system: 'Системная',
};

export default function AppearanceScreen({ onChange }: AppearanceScreenProps) {
  const [theme, setTheme] = useState<Theme>('system');
  const [scale, setScale] = useState<number>(100);
  const [dense, setDense] = useState<boolean>(false);
  const [font, setFont] = useState<Font>('system');

  const emit = (next: Partial<AppearanceSettings>) => {
    const settings: AppearanceSettings = {
      theme,
      scale,
      dense,
      font,
      ...next,
    };
    onChange?.(settings);
  };

  return (
    <JxPage>
      <JxPageHeader
        title="Внешний вид"
        description="Настройте тему, масштаб и плотность интерфейса"
        actions={<JxBadge variant="soft">{themeLabels[theme]}</JxBadge>}
      />

      <JxCard>
        <JxStack gap="lg">
          <JxStack gap="sm">
            <JxText weight="medium">Тема</JxText>
            <JxSegmentedControl
              value={theme}
              onChange={(value) => {
                const next = value as Theme;
                setTheme(next);
                emit({ theme: next });
              }}
            >
              <JxSegmentedItem value="light">Светлая</JxSegmentedItem>
              <JxSegmentedItem value="dark">Тёмная</JxSegmentedItem>
              <JxSegmentedItem value="system">Системная</JxSegmentedItem>
            </JxSegmentedControl>
          </JxStack>

          <JxStack gap="sm">
            <JxRow justify="space-between" align="center">
              <JxText weight="medium">Масштаб интерфейса</JxText>
              <JxBadge variant="outline">{scale}%</JxBadge>
            </JxRow>
            <JxSlider
              min={80}
              max={140}
              step={5}
              value={scale}
              onChange={(value) => {
                const next = Array.isArray(value) ? value[0] : value;
                setScale(next);
                emit({ scale: next });
              }}
            />
          </JxStack>

          <JxRow justify="space-between" align="center">
            <JxStack gap="none">
              <JxText weight="medium">Плотная вёрстка</JxText>
              <JxText variant="muted" size="sm">
                Уменьшает отступы и высоту строк
              </JxText>
            </JxStack>
            <JxSwitch
              checked={dense}
              onChange={(checked) => {
                setDense(checked);
                emit({ dense: checked });
              }}
            />
          </JxRow>

          <JxDivider />

          <JxStack gap="sm">
            <JxText weight="medium">Ещё</JxText>
            <JxStack gap="sm">
              <JxText variant="muted" size="sm">
                Шрифт интерфейса
              </JxText>
              <JxSelect
                value={font}
                onChange={(value) => {
                  const next = value as Font;
                  setFont(next);
                  emit({ font: next });
                }}
              >
                <JxSelectItem value="system">Системный</JxSelectItem>
                <JxSelectItem value="inter">Inter</JxSelectItem>
                <JxSelectItem value="mono">Моноширинный</JxSelectItem>
              </JxSelect>
            </JxStack>
          </JxStack>
        </JxStack>
      </JxCard>
    </JxPage>
  );
}

